fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since the two vectors have the same length (assumed),
    // iterate over the pairs and compare element-wise.
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x <= y)
        .collect()
}